import React, { useState, useEffect, useRef } from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

function AnimatedPath({ d }) {
  const pathRef = useRef(null);

  useEffect(() => {
    const path = pathRef.current;
    if (!path) return;

    const length = path.getTotalLength();

    path.style.strokeDasharray = length;
    path.style.strokeDashoffset = length;

    // Animate dashoffset from length to 0 on next frame
    requestAnimationFrame(() => {
      path.style.transition = 'stroke-dashoffset 1.2s ease-out';
      path.style.strokeDashoffset = '0';
    });
  }, [d]);

  return (
    <path
      ref={pathRef}
      d={d}
      fill="none"
      stroke="#60a5fa" // Tailwind blue-400
      strokeWidth="2"
    />
  );
}

function MemberCard({ img, title, name, onClick }) {
  return (
    <div
      onClick={onClick}
      className="cursor-pointer text-center p-4 border rounded shadow w-36 mx-auto bg-white hover:shadow-lg transition-shadow"
    >
      <img
        src={img}
        alt={title}
        className="w-20 h-20 mx-auto rounded-full mb-2 object-cover"
        loading="lazy"
      />
      <div className="font-semibold text-sm">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}

export default function CommitteeTree() {
  const [modalData, setModalData] = useState(null);

  // Positions (in px) for cards in a hierarchy tree layout
  // Adjust as needed for your container width/height
  // Coordinates relative to container top-left
  const positions = {
    president: { x: 320, y: 20 },
    vp: { x: 120, y: 140 },
    secretary: { x: 320, y: 140 },
    treasurer: { x: 520, y: 140 },
    members: [
      { x: 80, y: 280 },
      { x: 180, y: 280 },
      { x: 280, y: 280 },
      { x: 380, y: 280 },
      { x: 480, y: 280 },
      { x: 580, y: 280 },
      { x: 680, y: 280 },
      { x: 780, y: 280 },
    ],
  };

  // Define edges as Bezier curves between nodes
  // We'll use cubic bezier curve 'C' commands for smooth connections
  // Format: start(x,y), control points(x,y), end(x,y)
  const edges = [
    // President to VP
    {
      startX: positions.president.x + 72, // card center bottom (72 = half card width 144/2)
      startY: positions.president.y + 100, // card bottom (approx 100px height)
      control1: { x: positions.president.x + 72, y: positions.president.y + 140 },
      control2: { x: positions.vp.x + 72, y: positions.vp.y - 20 },
      endX: positions.vp.x + 72,
      endY: positions.vp.y,
    },
    // President to Secretary
    {
      startX: positions.president.x + 72,
      startY: positions.president.y + 100,
      control1: { x: positions.president.x + 72, y: positions.president.y + 140 },
      control2: { x: positions.secretary.x + 72, y: positions.secretary.y - 20 },
      endX: positions.secretary.x + 72,
      endY: positions.secretary.y,
    },
    // President to Treasurer
    {
      startX: positions.president.x + 72,
      startY: positions.president.y + 100,
      control1: { x: positions.president.x + 72, y: positions.president.y + 140 },
      control2: { x: positions.treasurer.x + 72, y: positions.treasurer.y - 20 },
      endX: positions.treasurer.x + 72,
      endY: positions.treasurer.y,
    },
    // Treasurer to Members (connecting first 4 members)
    {
      startX: positions.treasurer.x + 72,
      startY: positions.treasurer.y + 100,
      control1: { x: positions.treasurer.x + 72, y: positions.treasurer.y + 140 },
      control2: { x: positions.members[0].x + 72, y: positions.members[0].y - 20 },
      endX: positions.members[0].x + 72,
      endY: positions.members[0].y,
    },
    // Secretary to Members (connecting last 4 members)
    {
      startX: positions.secretary.x + 72,
      startY: positions.secretary.y + 100,
      control1: { x: positions.secretary.x + 72, y: positions.secretary.y + 140 },
      control2: { x: positions.members[4].x + 72, y: positions.members[4].y - 20 },
      endX: positions.members[4].x + 72,
      endY: positions.members[4].y,
    },
  ];

  // Handler to open modal with card details
  function openModal(data) {
    setModalData(data);
  }
  function closeModal() {
    setModalData(null);
  }

  return (
    <section
      className="relative bg-gray-50 py-10 px-4 max-w-[900px] mx-auto rounded-lg shadow-lg"
      style={{ minHeight: '400px' }}
    >
      <h2 className="text-3xl font-bold text-center mb-12">Our Committee</h2>

      {/* SVG edges behind cards */}
      <svg
        className="absolute top-0 left-0 w-full h-full pointer-events-none"
        style={{ zIndex: 0, overflow: 'visible' }}
      >
        {edges.map(({ startX, startY, control1, control2, endX, endY }, i) => {
          const d = `M${startX},${startY} C${control1.x},${control1.y} ${control2.x},${control2.y} ${endX},${endY}`;
          return <AnimatedPath key={i} d={d} />;
        })}
      </svg>

      {/* Cards container with relative positioning so cards appear above SVG */}
      <div className="relative z-10">
        {/* President */}
        <div
          style={{
            position: 'absolute',
            left: positions.president.x,
            top: positions.president.y,
          }}
        >
          <MemberCard
            {...roles[0]}
            onClick={() => openModal(roles[0])}
          />
        </div>

        {/* VP, Secretary, Treasurer */}
        {[1, 2, 3].map((idx) => {
          const role = roles[idx];
          const posKey = ['vp', 'secretary', 'treasurer'][idx - 1];
          return (
            <div
              key={idx}
              style={{
                position: 'absolute',
                left: positions[posKey].x,
                top: positions[posKey].y,
              }}
            >
              <MemberCard {...role} onClick={() => openModal(role)} />
            </div>
          );
        })}

        {/* Members */}
        {members.map((member, i) => (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: positions.members[i].x,
              top: positions.members[i].y,
            }}
          >
            <MemberCard {...member} onClick={() => openModal(member)} />
          </div>
        ))}
      </div>

      {/* Modal */}
      {modalData && (
        <div
          className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50"
          onClick={closeModal}
        >
          <div
            className="bg-white rounded-lg p-6 max-w-sm w-full shadow-lg relative"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              className="absolute top-2 right-2 text-gray-600 hover:text-gray-900"
              onClick={closeModal}
              aria-label="Close modal"
            >
              &times;
            </button>
            <img
              src={modalData.img}
              alt={modalData.title}
              className="w-32 h-32 mx-auto rounded-full mb-4 object-cover"
            />
            <h3 className="text-xl font-bold text-center mb-2">{modalData.title}</h3>
            <p className="text-center text-gray-700">{modalData.name}</p>
          </div>
        </div>
      )}
    </section>
  );
}
